import{_ as n,o as l,c as i,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"Lessons From Running Ceph as a Platform at Scale - Jason Burris, Sony Interactive Entertainment","description":"","frontmatter":{"title":"Lessons From Running Ceph as a Platform at Scale - Jason Burris, Sony Interactive Entertainment","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Ceph","分布式存储","可扩展性","高可用性","云存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Lessons_From_Running_Ceph_as_a_Platform_at_Scale_-_Jason_Burris_Sony_Interactive_Entertainment.md","filePath":"posts/2025/Lessons_From_Running_Ceph_as_a_Platform_at_Scale_-_Jason_Burris_Sony_Interactive_Entertainment.md","lastUpdated":1780459816000}'),r={name:"posts/2025/Lessons_From_Running_Ceph_as_a_Platform_at_Scale_-_Jason_Burris_Sony_Interactive_Entertainment.md"};function e(o,t,a,_,p,g){return l(),i("div",null,[...t[0]||(t[0]=[s("<p><strong>会议纪要：Ceph在大规模平台中的应用与经验分享</strong></p><p><strong>会议主题：</strong> Ceph在大规模平台中的应用与运营经验分享</p><p><strong>主讲人：</strong> Jason Burris，索尼互动娱乐（Sony Interactive Entertainment, SIE）存储平台产品负责人</p><p><strong>会议内容概述：</strong></p><p>Jason Burris分享了索尼互动娱乐（SIE）在构建和运营全球Ceph存储平台过程中的经验和教训。SIE的存储平台支持PlayStation和PlayStation Plus等产品，特别是云游戏流媒体服务。以下是会议的主要内容：</p><ol><li><p><strong>平台概况：</strong></p><ul><li>SIE拥有超过60个Ceph集群，总存储容量约为250PB，约30,000个硬盘驱动器（HDD），存储了约160亿个对象。</li><li>平台提供S3 API对象存储和RBD块存储，支持多个内部团队，目标是提供一流的存储服务。</li></ul></li><li><p><strong>平台构建与扩展：</strong></p><ul><li>从单个集群开始，逐步扩展到多个集群，并根据需求在不同地理位置构建集群以降低网络延迟。</li><li>考虑网络延迟、传输成本和可用性区域（Availability Zones），确保数据在不同集群之间的有效复制和同步。</li></ul></li><li><p><strong>客户支持与增长计划：</strong></p><ul><li>了解客户需求，明确平台支持的产品和客户类型。</li><li>制定增长计划，通常在存储使用率达到60%时开始扩展，确保平台在80%使用率以下运行。</li><li>提供自助服务功能，帮助其他团队（如SRE和运维团队）更好地管理和扩展存储平台。</li></ul></li><li><p><strong>集群管理与自动化：</strong></p><ul><li>使用Ansible进行集群的自动化部署和管理，确保跨多个集群的一致性。</li><li>开发了自定义的账户管理工具，用于在多个集群之间共享账户信息。</li><li>使用Prometheus和Grafana进行监控和仪表盘展示，优化了Prometheus的查询性能，减少了对Grafana的负载。</li></ul></li><li><p><strong>RGW用户指标与自动化：</strong></p><ul><li>开发了RGW利用率导出器，用于收集和展示用户级别的S3 API使用情况，帮助不同租户（Tenants）监控其存储使用情况。</li><li>讨论了是否将这些指标集成到Ceph开源项目中，以便其他用户也能受益。</li></ul></li><li><p><strong>故障处理与告警优化：</strong></p><ul><li>强调了避免过度依赖Ceph的警告状态（Warn Status）作为告警条件，建议使用更细粒度的告警策略。</li><li>引入服务水平目标（SLOs）来减少不必要的告警，确保告警更具操作性。</li><li>讨论了如何自动化驱动器更换流程，减少人工干预，特别是在全球部署中。</li></ul></li><li><p><strong>RBD性能优化：</strong></p><ul><li>分享了在处理大量RBD（块存储）时的性能问题，特别是在列出RBD时遇到的延迟问题。</li><li>通过引入命名空间（Namespaces）来优化RBD的管理，显著提高了RBD列表操作的性能。</li></ul></li><li><p><strong>经验总结：</strong></p><ul><li><strong>有目的地构建平台：</strong> 确保平台的设计和扩展符合客户需求，逐步成熟并支持更多产品。</li><li><strong>多租户支持：</strong> 理解多租户环境中的额外工作，并通过自动化和监控来简化管理。</li><li><strong>为故障做好准备：</strong> 预见并计划应对硬件和网络故障，确保平台的弹性和恢复能力。</li><li><strong>赋能团队：</strong> 通过自动化、监控和文档化，让所有团队都能更好地理解和使用存储平台。</li></ul></li></ol><p><strong>后续行动计划：</strong></p><ul><li>继续优化自动化工具，特别是Ansible和Ceph Bot，以提高集群管理的效率。</li><li>探索将RGW用户指标集成到Ceph开源项目中的可能性，与社区合作改进Ceph的功能。</li><li>进一步优化RBD的性能，特别是在大规模集群中的管理效率。</li></ul><p><strong>问答环节：</strong></p><ul><li>讨论了如何使用Ansible进行大规模部署，以及如何管理多个集群之间的账户一致性。</li><li>提到了当前平台运行在裸金属服务器上，未来可能会考虑容器化。</li><li>强调了在升级Ceph版本时需要谨慎，避免过快升级导致潜在问题。</li></ul><p><strong>总结：</strong> Jason Burrus的分享为Ceph在大规模平台中的应用提供了宝贵的经验和最佳实践，特别是在多租户、自动化、性能优化和故障处理方面。通过这些经验，SIE成功构建了一个高效、可靠的全球存储平台，支持了多个关键业务产品。</p>",11)])])}const S=n(r,[["render",e]]);export{m as __pageData,S as default};
